"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9524],{36506:e=>{e.exports=JSON.parse('{"functions":[{"name":"calculate","desc":"Returns the level a given lifetime XP total corresponds to.\\n\\nThe inverse of [Level.xpRequired] \u2014 level 1 starts at 0 XP.","params":[{"name":"xp","desc":"Total lifetime XP","lua_type":"number"}],"returns":[{"desc":"Current level","lua_type":"number"}],"function_type":"static","source":{"line":47,"path":"src/Shared/Modules/Level.luau"}},{"name":"xpRequired","desc":"Returns the cumulative XP needed to reach `level`, as `32 * level\xb2 - 32 * level`.\\n\\nThis is a lifetime total, not the cost of that one level \u2014 subtract the previous\\nlevel\'s requirement (or use [Level.xpGap]) for that.","params":[{"name":"level","desc":"Level to reach","lua_type":"number"}],"returns":[{"desc":"Total XP required","lua_type":"number"}],"function_type":"static","source":{"line":63,"path":"src/Shared/Modules/Level.luau"}},{"name":"xpGap","desc":"Returns how much XP the player\'s current level costs end to end \u2014 the distance\\nbetween the current level\'s threshold and the next one\'s.\\n\\nThis is the size of the current level, not the XP still remaining in it.","params":[{"name":"xp","desc":"Total lifetime XP","lua_type":"number"}],"returns":[{"desc":"XP spanned by the current level","lua_type":"number"}],"function_type":"static","source":{"line":79,"path":"src/Shared/Modules/Level.luau"}},{"name":"progressPercentage","desc":"Returns how far through the current level the player is, as a 0-1 fraction.","params":[{"name":"xp","desc":"Total lifetime XP","lua_type":"number"}],"returns":[{"desc":"Progress through the current level, 0 to 1","lua_type":"number"}],"function_type":"static","source":{"line":93,"path":"src/Shared/Modules/Level.luau"}},{"name":"getOverview","desc":"Bundles level, progress and thresholds for an XP total into one table.\\n\\n```lua\\nlocal overview = Level.getOverview(profile.xp)\\n\\nlevelLabel.Text = `Level {overview.level}`\\nbar.Size = UDim2.fromScale(overview.levelProgress, 1)\\n```","params":[{"name":"xp","desc":"Total lifetime XP","lua_type":"number"}],"returns":[{"desc":"","lua_type":"LevelOverview"}],"function_type":"static","source":{"line":116,"path":"src/Shared/Modules/Level.luau"}}],"properties":[],"types":[{"name":"LevelOverview","desc":"Everything a progress bar needs, computed in one pass.","fields":[{"name":"xp","lua_type":"number","desc":"Total lifetime XP"},{"name":"level","lua_type":"number","desc":"Level that XP total corresponds to"},{"name":"xpProgress","lua_type":"number","desc":"XP earned so far within the current level"},{"name":"xpRequired","lua_type":"number","desc":"XP the current level costs in total"},{"name":"levelProgress","lua_type":"number","desc":"`xpProgress / xpRequired`, from 0 to 1"}],"source":{"line":26,"path":"src/Shared/Modules/Level.luau"}}],"name":"Level","desc":"Helper functions for XP and level calculations.\\n\\nLevels follow a quadratic curve: reaching level `n` costs `32n\xb2 - 32n` total XP,\\nso each level is a little more expensive than the last. XP is the only stored\\nvalue \u2014 level, progress and the XP gap are all derived from it, which means a\\nplayer\'s level cannot drift out of sync with their XP.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":14,"path":"src/Shared/Modules/Level.luau"}}')}}]);